// Material code: runs once per hit (cheap), after the fields above are put into m.
//   m        the Material2 to change -- m.baseColor, m.roughness, m.metallic, m.emissive, ...
//   p, n     the hit point and surface normal, world space;  C  the Hit
//   p_local  the hit in the object's own frame, so a pattern moves with the object
//            (costs one extra SDF evaluation per hit on this material)
//   R_local  that frame's rotation to the world, for a direction written in it
//   S_local  its scale: p_local * S_local is in scene units, and metres(x) is x m in them
//   your own parameters (+ in the parameters header) by name, e.g. a colour stripe
// e.g. a checker fixed in the world:
//   m.baseColor = mix(m.baseColor, VEC3(0.05), step(0.0, sin(p.x * 3.0) * sin(p.y * 3.0) * sin(p.z * 3.0)));
// e.g. stripes that travel with the object:
//   m.roughness = step(0.5, fract(p_local.x * 4.0)) * 0.6;
// e.g. brushed along the object's x, for an anisotropy above 0 (or turned: grainAround):
//   m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// e.g. with a number width and a colour stripe added with +:
//   m.baseColor = mix(m.baseColor, stripe, step(fract(p.x / width), 0.5));

// Material code: runs once per hit (cheap), after the fields above are put into m.
//   m        the Material2 to change -- m.baseColor, m.roughness, m.metallic, m.emissive, ...
//   p, n     the hit point and surface normal, world space;  C  the Hit
//   p_local  the hit in the object's own frame, so a pattern moves with the object
//            (costs one extra SDF evaluation per hit on this material)
//   R_local  that frame's rotation to the world, for a direction written in it
//   S_local  its scale: p_local * S_local is in scene units, and metres(x) is x m in them
//   your own parameters (+ in the parameters header) by name, e.g. a colour stripe
// e.g. a checker fixed in the world:
//   m.baseColor = mix(m.baseColor, VEC3(0.05), step(0.0, sin(p.x * 3.0) * sin(p.y * 3.0) * sin(p.z * 3.0)));
// e.g. stripes that travel with the object:
//   m.roughness = step(0.5, fract(p_local.x * 4.0)) * 0.6;
// e.g. brushed along the object's x, for an anisotropy above 0 (or turned: grainAround):
//   m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// e.g. with a number width and a colour stripe added with +:
//   m.baseColor = mix(m.baseColor, stripe, step(fract(p.x / width), 0.5));

// vnoise3: value noise, [-1, 1]. The base colour and roughness where it is low, the second ones
// where it is high; one cell every `size` mm.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let t = 0.5 + 0.5 * vnoise3(q / size, 1u).w;
m.baseColor = mix(m.baseColor, second, t);
m.roughness = mix(m.roughness, secondRough, t);

// gnoise3: gradient noise, about [-1, 1]: smoother and less grid-bound than value noise. The base
// colour and roughness where it is low, the second ones where it is high; one cell every `size` mm.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let t = 0.5 + 0.5 * gnoise3(q / size, 2u).w;
m.baseColor = mix(m.baseColor, second, t);
m.roughness = mix(m.roughness, secondRough, t);

// fbm3: five octaves, bending sine bands into veins -- polished marble. size is the noise's cell
// in mm; veins how many bands to a cell; turbulence how far it bends them; sharpness how thin.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let nz = fbm3(q / size, 3u, 5u, 2.0, 0.5);
let v = pow(1.0 - abs(sin(veins * (q.x / size + turbulence * nz.w))), sharpness);
m.baseColor = mix(m.baseColor, vein, v);

// worley3 F1: the distance to the nearest cell point -- round spots at each point, on the base
// colour. spacing is the distance between points in mm; spotRadius a spot's size, as a share of it.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3(q / spacing, 4u);
m.baseColor = mix(spot, m.baseColor, smoothstep(spotRadius - softness, spotRadius + softness, w.x));

// worley3 F2 - F1: zero on a cell border -- the creases of grained leather, rougher and darker.
// The hide is the base colour and roughness; cell is a grain's size in mm.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3(q / cell, 5u);
let crease = 1.0 - smoothstep(0.0, creaseWidth, w.y - w.x);
m.baseColor = mix(m.baseColor, creaseColor, crease);
m.roughness = mix(m.roughness, creaseRough, crease);

// worley3 cell number: each grain its own mineral -- light (the base colour), pink or dark --
// as in granite. grain is a crystal's size in mm; the shares are how many are pink and dark.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3(q / grain, 6u);
let c = select(select(m.baseColor, pink, w.z < darkShare + pinkShare), dark, w.z < darkShare);
m.baseColor = c * (1.0 - edge + edge * smoothstep(0.0, 0.1, w.y - w.x));

